#pragma once
namespace openp1::network {
constexpr char diagnostics_page[]=R"HTML(<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenP1 diagnostics</title><style>:root{font:16px system-ui;color:#193c35;background:#f1f5f3}*{box-sizing:border-box}body{max-width:1500px;margin:auto;padding:28px 20px}header{display:flex;justify-content:space-between;align-items:center;gap:16px}h1{font-size:32px;letter-spacing:-.04em;margin:8px 0}h2{font-size:19px;margin:0 0 16px}p,small{line-height:1.6}small{color:#637b72}a{color:#17664f}a:focus-visible{outline:3px solid #5bb997;outline-offset:4px}.columns{display:grid;grid-template-columns:1fr 1.5fr 1fr;gap:16px;margin:24px 0}.panel{background:white;border:1px solid #dae5df;border-radius:16px;padding:20px;min-width:0}.scroll{max-height:65vh;overflow:auto}pre{font:12px ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#f0f5f2;padding:12px;border-radius:8px}article{border-bottom:1px solid #e4ece7;padding-bottom:14px;margin-bottom:14px}article p{font-size:12px;color:#637b72}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:12px 6px;text-align:left;vertical-align:top;border-bottom:1px solid #e4ece7;overflow-wrap:anywhere}td small{display:block;font-size:11px}.stale{color:#9b621b}#diagStatus{padding:12px 16px;background:#e4efe8;border-radius:10px}#diagStatus[data-error=true]{color:#a0332b;background:#fff0ed}#diagErrors p{font-size:13px;overflow-wrap:anywhere}@media(max-width:1050px){.columns{grid-template-columns:1fr}.scroll{max-height:430px}body{padding:20px 14px}}</style>
<header><div><small>OPENP1 · READ-ONLY</small><h1>Diagnostics</h1></div><a href="/">← Readings</a></header><p id="diagStatus" role="status" aria-live="polite">Connecting…</p><small>Refreshes every 3 seconds. Meter identifiers may appear in raw and decoded data. Times are relative to device startup.</small>
<main class="columns"><section class="panel"><h2>Raw bytes</h2><small id="diagRawInfo">Latest input chunks</small><p><small>This limited tail may start mid-frame. Chunks are not necessarily complete HDLC frames. Raw and decoded panels are separate snapshots.</small></p><div id="diagRaw" class="scroll"></div></section>
<section class="panel"><h2>Decoded values</h2><small>Last known scalar/string values, including unknown OBIS codes. Nested unsupported values are not listed here.</small><div class="scroll"><table><thead><tr><th>OBIS / name</th><th>Value / metadata</th><th>Age</th></tr></thead><tbody id="diagValues"></tbody></table></div></section>
<section class="panel"><h2>Errors &amp; status</h2><div id="diagErrors"></div><small>Counters and the latest parser error since restart. An invalid frame does not replace good readings with zero. No error-history log is recorded.</small></section></main>
<script>
const diag=Object.fromEntries(['diagStatus','diagRawInfo','diagRaw','diagValues','diagErrors'].map(id=>[id,document.getElementById(id)]));
async function diagRead(path){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const r=await fetch(path,{cache:'no-store',signal:controller.signal});if(!r.ok){const error=Error(r.status===403?'Access unavailable. Press S2 for Full access.':'Device response unavailable (HTTP '+r.status+').');error.status=r.status;throw error}return await r.json()}catch(e){if(controller.signal.aborted)throw Error('Device response timed out. Retrying…');throw e}finally{clearTimeout(timer)}}
function diagCell(parent,tag,text){const node=document.createElement(tag);node.textContent=text;parent.append(node);return node}
function diagNumber(value){return Number.isFinite(value)?String(value):'—'}
function showDiagnostics(d,r){
diag.diagStatus.dataset.error='false';diag.diagStatus.textContent=(d.simulation?'Simulation':'Meter UART')+' · access '+(d.access||'unavailable')+' · uptime '+diagNumber(d.uptime_ms)+' ms';
diag.diagRawInfo.textContent='Latest '+r.records.length+' / '+diagNumber(r.limit)+' chunks · pipeline overwrites '+diagNumber(r.history_overwritten);
diag.diagRaw.replaceChildren();for(const chunk of r.records){const card=document.createElement('article');diagCell(card,'p','#'+chunk.sequence+' · '+chunk.timestamp_ms+' ms · '+chunk.source+' · '+chunk.layer);diagCell(card,'pre',chunk.hex);diag.diagRaw.append(card)}if(!r.records.length)diagCell(diag.diagRaw,'p','No raw bytes received yet.');
diag.diagValues.replaceChildren();for(const value of d.values){const row=document.createElement('tr');row.className=value.stale?'stale':'';const name=diagCell(row,'td',value.obis_display||value.obis);diagCell(name,'small',value.name||'Unknown OBIS');const detail=diagCell(row,'td',String(value.value??'Unavailable')+(value.unit?' '+value.unit:'')+(value.value_encoding==='hex'?' (hex)':''));diagCell(detail,'small','Type '+diagNumber(value.type)+' · sample '+diagNumber(value.timestamp_ms)+' ms');if(value.has_scaler_unit)diagCell(detail,'small','Raw '+value.raw_value+' · scaler '+value.scaler+' · unit code '+value.unit_code);diagCell(row,'td',diagNumber(value.age_ms)+' ms'+(value.stale?' · stale':''));diag.diagValues.append(row)}if(!d.values.length){const row=document.createElement('tr');diagCell(row,'td','No decoded scalar/string values yet.');diag.diagValues.append(row)}
diag.diagErrors.replaceChildren();for(const [name,value] of [['Parser errors',diagNumber(d.errors)],['Latest error',Number.isFinite(d.errors)?(d.errors?d.last_error:'None'):'Unavailable'],['Error timestamp (ms)',diagNumber(d.last_error_ms)],['Validated HDLC messages',diagNumber(d.validated_hdlc)],['Decoded messages',diagNumber(d.notifications)],['Free RAM (bytes)',diagNumber(d.free_heap_bytes)],['Largest free block (bytes)',diagNumber(d.largest_free_block_bytes)]])diagCell(diag.diagErrors,'p',name+': '+value);
}
async function refreshDiagnostics(){let denied=false;try{const values=await diagRead('/api/v1/values');const raw=await diagRead('/api/v1/raw');if(!Array.isArray(values.values)||!Array.isArray(raw.records))throw Error('Incomplete diagnostics response. Retrying…');showDiagnostics(values,raw)}catch(e){diag.diagRaw.replaceChildren();diag.diagValues.replaceChildren();diag.diagErrors.replaceChildren();diag.diagStatus.dataset.error='true';diag.diagStatus.textContent=e.message;if(e.status===403){denied=true;location.replace('/unlock')}}finally{if(!denied)setTimeout(refreshDiagnostics,3000)}}refreshDiagnostics();
</script></html>)HTML";
}
